<?php
namespace App\Models; use App\Domain\Foundation\Traits\BelongsToCollege; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo;
class LibraryFine extends Model { use BelongsToCollege; const TYPE_OVERDUE='overdue', TYPE_LOST_DAMAGED='lost_damaged'; const STATUS_PENDING='pending', STATUS_ASSESSED='assessed', STATUS_WAIVED='waived', STATUS_PAID='paid'; protected $fillable=['college_id','library_transaction_id','library_member_id','type','period_start','period_end','days_overdue','rate_per_day','assessed_amount','paid_amount','status','payment_reference','assessed_by','paid_by','assessed_at','paid_at','remarks','created_by','updated_by']; protected function casts():array{return ['period_start'=>'date','period_end'=>'date','rate_per_day'=>'decimal:2','assessed_amount'=>'decimal:2','paid_amount'=>'decimal:2','assessed_at'=>'datetime','paid_at'=>'datetime'];} public function transaction():BelongsTo{return $this->belongsTo(LibraryTransaction::class,'library_transaction_id');} public function member():BelongsTo{return $this->belongsTo(LibraryMember::class,'library_member_id');} public function outstanding():string{return bcsub((string)$this->assessed_amount,(string)$this->paid_amount,2);}}
